"""Build a portable gallery for the actual PNG layers; no reconstructed artwork."""
import json
from pathlib import Path
from PIL import Image
R=Path(__file__).resolve().parents[1]
parts=json.loads((R/'manifest.json').read_text())['parts']
for p in parts:
 p['box']=list(Image.open(R/'parts'/p['id']/'shape.png').getbbox())
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>90 部件 · 灰底清空与遮挡补全</title>
<style>*{box-sizing:border-box}body{margin:0;color:#edf0f5;background:#20232a;font:15px/1.6 system-ui,sans-serif}header{padding:20px 28px;background:#292d35;border-bottom:1px solid #454a56}h1{font-size:22px;margin:0 0 8px}a{color:#b4d9ff}p{margin:7px 0}main{display:grid;grid-template-columns:300px 1fr;min-height:85vh}aside{padding:16px;max-height:86vh;overflow:auto;border-right:1px solid #454a56}button,select{font:inherit;background:#353b47;color:#fff;border:1px solid #626b7a;border-radius:5px;padding:6px 10px;cursor:pointer}button.active{background:#415774}aside button{display:block;text-align:left;width:100%;margin-bottom:5px;overflow-wrap:anywhere;font-size:12px}article{padding:20px;overflow:auto}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}#info{color:#bfc8d8}#panels{display:flex;gap:22px;align-items:start;flex-wrap:wrap}.card h3{font-size:13px;color:#ced6e5}.crop{position:relative;overflow:hidden;background-color:#dcdcdc;background-image:linear-gradient(45deg,#c8c8c8 25%,transparent 25%),linear-gradient(-45deg,#c8c8c8 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#c8c8c8 75%),linear-gradient(-45deg,transparent 75%,#c8c8c8 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}.crop img{position:absolute;max-width:none;width:1024px;height:1536px}.whole{display:flex;gap:20px;align-items:start}.whole img{width:512px;height:768px;background:#dadada}#name{font-size:17px;overflow-wrap:anywhere}.hint{font-size:13px;color:#bbc5d5}@media(max-width:750px){main{grid-template-columns:1fr}aside{max-height:250px;border-bottom:1px solid #454a56}}</style>
<header><h1>90 部件 · 灰底清空、模型补全与 Krita 修画</h1><p><a href="character-depth.kra" download>下载分层 Krita 工程</a> · <a href="README.md">制作与验收报告</a> · <a href="preview.png">透明整图 PNG</a> · <a href="generation-provenance.json">生成记录</a></p><p class="hint">每个部件一个绘画图层，按参考深度从下到上排列。选择左侧部件，以原尺寸查看独立补全。</p></header>
<main><aside id="list"></aside><article><nav><button id="all">整图对照</button><button id="prev">上一层</button><button id="next">下一层</button><button id="native">整图 100%</button></nav><h2 id="name"></h2><p id="info"></p><div id="panels"></div></article></main>
<script>const parts=PARTS;let active=-1,wholeNative=false;const $=id=>document.getElementById(id);function show(i){active=i;document.querySelectorAll('aside button').forEach((b,n)=>b.classList.toggle('active',n===i));$('panels').replaceChildren();if(i<0){$('name').textContent='原图与透明分层合成';$('info').textContent='原图背景光晕不属于人物图层；相似度按整体观感检查。';const d=document.createElement('div');d.className='whole';for(const f of ['reference.png','preview.png']){const im=document.createElement('img');im.src=f;im.alt=f;im.style.width=(wholeNative?1024:512)+'px';im.style.height=(wholeNative?1536:768)+'px';d.append(im)}$('panels').append(d);return}const p=parts[i];$('name').textContent=String(p.level).padStart(2,'0')+' '+p.id;$('info').textContent='原尺寸 1:1 · 完整画布 1024 × 1536 · 红色保留，黄色补全，绿色透明';const b=p.box.map((v,j)=>v+(j<2?-4:4));b[0]=Math.max(0,b[0]);b[1]=Math.max(0,b[1]);b[2]=Math.min(1024,b[2]);b[3]=Math.min(1536,b[3]);for(const [label,f] of [['原图局部','reference.png'],['RGB 控制图','parts/'+p.id+'/control.png'],['灰底清空输入','parts/'+p.id+'/input.png'],['最终完整部件','parts/'+p.id+'/full.png']]){const card=document.createElement('section');card.className='card';const title=document.createElement('h3');title.textContent=label;const crop=document.createElement('div');crop.className='crop';crop.style.width=b[2]-b[0]+'px';crop.style.height=b[3]-b[1]+'px';const im=document.createElement('img');im.src=f;im.alt=label+' '+p.id;im.style.left=-b[0]+'px';im.style.top=-b[1]+'px';crop.append(im);card.append(title,crop);$('panels').append(card)}}parts.forEach((p,i)=>{const b=document.createElement('button');b.textContent=String(p.level).padStart(2,'0')+' '+p.id;b.onclick=()=>show(i);$('list').append(b)});$('all').onclick=()=>show(-1);$('prev').onclick=()=>show(Math.max(0,active-1));$('next').onclick=()=>show(Math.min(parts.length-1,active+1));$('native').onclick=()=>{wholeNative=!wholeNative;show(-1)};show(-1);</script></html>'''
(R/'index.html').write_text(page.replace('PARTS',json.dumps(parts,ensure_ascii=False)))
